Method.Implementation:
#dim tSC As %Status=$$$OK $$$TRACE("Inside Method ProcessHttpsRequest") Set initiateMrn = pRequest.mrnNum $$$TRACE("InitiateMRN#: "_initiateMrn) set URL = ..Adapter.URL $$$TRACE("EndPoint URL: "_URL)
set pstatus=##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.GenericDemogrXmlEpsEMPIINVESTIGATOR.InitiateMpiProperties","X_API_KEY",.retVal) set xApiKey = retVal
Set httprequest=##class(%Net.HttpRequest).%New() Set httprequest.ContentType="text/plain" do httprequest.SetHeader("x-api-key",xApiKey) Set httprequest.Https="1" Set httprequest.SSLConfiguration = ..Adapter.SSLConfig Set httprequest.Location = ..Adapter.URL
Set jsonRequest = "{""emmi_no"": """_initiateMrn_""", ""service_call_uuid_token"": ""test""}"
Set pResponse=##class(Ens.StringResponse).%New() try{ Do httprequest.EntityBody.Write(jsonRequest) ;
$$$TRACE("Calling Cern Drc DuplicateId Service.....")
set postStatus = httprequest.Post(URL) set postStatusTxt = $SYSTEM.Status.GetOneErrorText(postStatus) $$$TRACE("postStatusTxt--> "_postStatusTxt) set response=httprequest.HttpResponse $$$TRACE("StatusLine: "_response.StatusLine) if (postStatus =1){ $$$TRACE(" Cerner Drc DuplicateId call success!!!") set len = httprequest.HttpResponse.ContentLength set respData = httprequest.HttpResponse.Data.Read() $$$TRACE("RESP DATA ???? "_respData) set consumedJSONobj = ##class(%DynamicAbstractObject).%FromJSON(respData) set statusVal = ((consumedJSONobj.%Get("response")).%Get("service-status")).%Get("status") $$$TRACE(" statusVal: "_statusVal) if (statusVal="SUCCESS"){ set dupIds = "" set statusDetailsArr = ((consumedJSONobj.%Get("response")).%Get("status-details")) $$$TRACE(" statusDetailsArr: "_statusDetailsArr) // Loop through a JSON Array Set arrObj = statusDetailsArr.%GetIterator()
while arrObj.%GetNext(.key, .value) { Set arrElemObj = value.%GetIterator() while arrElemObj.%GetNext(.key, .value) { $$$TRACE(" key: "_key_" Value: "_value) if (key = "DUPLICATE_ID"){ Set dupIds = value_"|"_dupIds } } } } $$$TRACE(" dupIds: "_dupIds) Set pResponse.StringValue = dupIds
}
}catch e{ set errTxt = $System.Status.GetErrorText("Unknown Exception while calling Cerner Drc DuplicateId call "_e) $$$TRACE(" Unknown Exception: " _ errTxt) Set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Op-Generic-Demogr-Json-DRCDUPLICATES",errTxt) }
quit tSC
